// netlify/functions/hnh-fixtures.js
//
// The UK/Irish racing fixture list. Static data, so no subscription needed -
// the BHA publishes the whole year in advance.
//
// IMPORT (paste CSV, one fixture per line):
//   POST /.netlify/functions/hnh-fixtures?pw=PASSWORD
//   Body: raw CSV text, or JSON array
//
//   Accepted CSV shapes (header row optional, order flexible):
//     date,course,code
//     2026-09-10,Doncaster,flat
//     2026-09-10,Sedgefield,jumps
//
//   Codes: flat, jumps (aw counts as flat, nh counts as jumps)
//
// QUERY:
//   GET ?pw=PASSWORD&next=jumps          next jumps fixture
//   GET ?pw=PASSWORD&date=2026-09-10     everything that day
//   GET ?pw=PASSWORD&days=7              the next week
//   GET ?pw=PASSWORD&course=Doncaster    next few at one course
//   GET ?pw=PASSWORD&stats=1             what is loaded

import { getStore } from '@netlify/blobs';

const STORE = 'hnh-events';
const KEY = 'fixtures/list';

// ===========================================================================
// ==  THE 2026 FIXTURE LIST                                                ==
// ==                                                                       ==
// ==  All 1,458 British fixtures, parsed from the BHA's published list at  ==
// ==  media.britishhorseracing.com/bha/Fixture_List/2026_Fixture_List.pdf  ==
// ==                                                                       ==
// ==  Encoded compactly: c = course names, d = date -> [courseIndex,       ==
// ==  isFlat, flags] where flags bit 1 = evening, bit 2 = floodlit.        ==
// ==  Codes come from the BHA's own convention: CAPITALS are Flat          ==
// ==  meetings, Title Case are Jump meetings.                              ==
// ==                                                                       ==
// ==  Static data, so no subscription and no imports needed. Replace this  ==
// ==  block when the 2027 list is published.                               ==
// ===========================================================================

