function builtInFixtures() {
  const out = [];
  for (const [date, entries] of Object.entries(FIXTURE_DATA.d)) {
    for (const [ci, isFlat, flags] of entries) {
      out.push({
        date,
        course: FIXTURE_DATA.c[ci],
        code: isFlat ? 'flat' : 'jumps',
        evening: !!(flags & 1),
        floodlit: !!(flags & 2),
      });
    }
  }
  return out.sort((a, b) => a.date.localeCompare(b.date) || a.course.localeCompare(b.course));
}

const json = (body, status = 200) =>
  new Response(JSON.stringify(body, null, 2), {
    status,
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store' },
  });

function ukDate(d) {
  const dt = d instanceof Date ? d : new Date(d || Date.now());
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(dt);
}

function addDays(iso, n) {
  const dt = new Date(`${iso}T12:00:00Z`);
  dt.setUTCDate(dt.getUTCDate() + n);
  return dt.toISOString().slice(0, 10);
}

/**
 * Normalise however the code is written. Sources vary: "Jump", "NH",
 * "National Hunt", "AW", "All Weather", "Flat Turf".
 */
function normaliseCode(raw) {
  const s = String(raw || '').trim().toLowerCase();
  if (!s) return null;
  if (/jump|nh|national hunt|hurdle|chase/.test(s)) return 'jumps';
  if (/flat|aw|all.?weather|turf|polytrack|tapeta/.test(s)) return 'flat';
  return null;
}

/**
 * Dates arrive in whatever the source used. Handle the common British
 * formats rather than assuming ISO.
 */
function normaliseDate(raw) {
  const s = String(raw || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;

  // dd/mm/yyyy or dd-mm-yyyy
  let m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
  if (m) {
    const [, d, mo, y] = m;
    return `${y}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  }

  // "10 September 2026" / "10 Sep 2026"
  const months = {
    jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06',
    jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12',
  };
  m = s.match(/^(\d{1,2})\s+([a-z]+)\s+(\d{4})$/i);
  if (m) {
    const mo = months[m[2].slice(0, 3).toLowerCase()];
    if (mo) return `${m[3]}-${mo}-${String(m[1]).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Parse pasted fixture data. Deliberately forgiving about column order and
 * separators, because the data will be copied from a website or a
 * spreadsheet rather than a clean export.
 */
function parseFixtures(raw) {
  const text = String(raw || '').trim();
  if (!text) return { fixtures: [], skipped: [] };

  // Already JSON?
  if (text.startsWith('[')) {
    try {
      const arr = JSON.parse(text);
      const fixtures = [];
      const skipped = [];
      for (const f of arr) {
        const date = normaliseDate(f.date);
        const course = String(f.course || f.venue || f.track || '').trim();
        const code = normaliseCode(f.code || f.type || f.discipline);
        if (date && course) fixtures.push({ date, course, code });
        else skipped.push(JSON.stringify(f).slice(0, 60));
      }
      return { fixtures, skipped };
    } catch { /* fall through to CSV */ }
  }

  const fixtures = [];
  const skipped = [];

  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^date\b/i.test(trimmed)) continue; // header

    const parts = trimmed.split(/\s*[,;\t|]\s*/).filter(Boolean);
    if (parts.length < 2) { skipped.push(trimmed.slice(0, 60)); continue; }

    // Find the date wherever it is, rather than assuming column one.
    let date = null, dateIdx = -1;
    for (let i = 0; i < parts.length; i++) {
      const d = normaliseDate(parts[i]);
      if (d) { date = d; dateIdx = i; break; }
    }
    if (!date) { skipped.push(trimmed.slice(0, 60)); continue; }

    const rest = parts.filter((_, i) => i !== dateIdx);
    let code = null, course = null;
    for (const p of rest) {
      const c = normaliseCode(p);
      if (c && !code) code = c;
      else if (!course) course = p;
    }
    if (!course && rest.length) course = rest[0];
    if (!course) { skipped.push(trimmed.slice(0, 60)); continue; }

    fixtures.push({ date, course: course.trim(), code });
  }

  return { fixtures, skipped };
}

/**
 * Imported fixtures win if present, so a future year can be loaded without
 * touching the code. Otherwise the built-in 2026 list is used.
 */
async function loadFixtures() {
  try {
    const v = await getStore(STORE).get(KEY, { type: 'json' });
    if (Array.isArray(v) && v.length) return v;
  } catch { /* fall through */ }
  return builtInFixtures();
}

export default async (req) => {
  const url = new URL(req.url);
  if (url.searchParams.get('pw') !== process.env.ADMIN_PASSWORD) {
    return new Response('unauthorised', { status: 401 });
  }

  const store = getStore(STORE);

  // ---- import ----
  if (req.method === 'POST') {
    try {
      const body = await req.text();
      const { fixtures, skipped } = parseFixtures(body);
      if (!fixtures.length) {
        return json({ error: 'nothing parsed', skipped: skipped.slice(0, 10) }, 400);
      }

      const merge = url.searchParams.get('merge') === '1';
      const existing = merge ? await loadFixtures() : [];

      // Dedupe on date + course, so re-importing is safe.
      const seen = new Set(existing.map((f) => `${f.date}|${f.course.toLowerCase()}`));
      const added = [];
      for (const f of fixtures) {
        const k = `${f.date}|${f.course.toLowerCase()}`;
        if (seen.has(k)) continue;
        seen.add(k);
        added.push(f);
      }

      const all = [...existing, ...added].sort(
        (a, b) => a.date.localeCompare(b.date) || a.course.localeCompare(b.course)
      );
      await store.setJSON(KEY, all);

      const codes = {};
      for (const f of all) codes[f.code || 'unknown'] = (codes[f.code || 'unknown'] || 0) + 1;

      return json({
        ok: true,
        imported: added.length,
        totalStored: all.length,
        firstDate: all[0] ? all[0].date : null,
        lastDate: all.length ? all[all.length - 1].date : null,
        byCode: codes,
        skippedLines: skipped.length,
        skippedSamples: skipped.slice(0, 5),
      });
    } catch (err) {
      return json({ error: err.message }, 400);
    }
  }

  // ---- query ----
  const all = await loadFixtures();
  const today = ukDate();

  if (url.searchParams.get('stats') === '1') {
    const codes = {};
    for (const f of all) codes[f.code || 'unknown'] = (codes[f.code || 'unknown'] || 0) + 1;
    const upcoming = all.filter((f) => f.date >= today);
    return json({
      totalStored: all.length,
      upcoming: upcoming.length,
      firstDate: all[0] ? all[0].date : null,
      lastDate: all.length ? all[all.length - 1].date : null,
      byCode: codes,
      dataPresent: all.length > 0,
    });
  }

  const nextCode = url.searchParams.get('next');
  if (nextCode) {
    const code = normaliseCode(nextCode);
    const matches = all
      .filter((f) => f.date >= today && (!code || f.code === code))
      .slice(0, 10);
    return json({
      query: `next ${code || 'fixture'}`,
      today,
      next: matches[0] || null,
      following: matches.slice(1, 6),
    });
  }

  const course = url.searchParams.get('course');
  if (course) {
    const c = course.toLowerCase();
    return json({
      course,
      fixtures: all.filter((f) => f.date >= today && f.course.toLowerCase().includes(c)).slice(0, 10),
    });
  }

  const date = url.searchParams.get('date');
  if (date) {
    const d = normaliseDate(date) || date;
    return json({ date: d, fixtures: all.filter((f) => f.date === d) });
  }

  const days = Math.min(parseInt(url.searchParams.get('days'), 10) || 7, 90);
  const end = addDays(today, days);
  const window = all.filter((f) => f.date >= today && f.date <= end);

  const byDate = {};
  for (const f of window) {
    if (!byDate[f.date]) byDate[f.date] = [];
    byDate[f.date].push({ course: f.course, code: f.code });
  }

  return json({ from: today, to: end, days, count: window.length, byDate });
};
